package ui

import (
	_ "embed"

	"fyne.io/fyne/v2"
)

// soulIconPNG is the embedded Soul App logo (generated by scripts/generate_icon.py).
//
//go:embed assets/soul.png
var soulIconPNG []byte

// appIcon is the shared application icon used by the Fyne application, the main
// window and the system tray entry.
var appIcon = fyne.NewStaticResource("soul.png", soulIconPNG)

// AppIcon returns the embedded Soul App icon resource.
func AppIcon() fyne.Resource {
	return appIcon
}
